comments.message:
this and the following index math is difficult to grok. looks to me like this could be simplified somewhat by defining a couple of structs.

```
struct port_header
{
    ocp::accelerator_management::CommonResponse;
    uint16_t whatever_this_is;
} __attribute__((packed));

struct port_data
{
    uint8_t isInternal;
    uint8_t downstreamPorts;
} __attribute__((packed))

// ....

size_t offset = sizeof(port_header) + i * sizeof(port_data);
if (offset + sizeof(port_data)) > buf.size())
{
    return EINVAL;
}

struct port_data data;
std::memcpy(&data, &buf[offset], sizeof(data));

if (data.isInternal == 0)
{
    ++numUpstreamPorts;
    numDownStreamPorts.push_back(downstreamPorts);
}
```

you could also just keep an iterator and use std::distance to buf.end() instead
